def text(language: str, key: str, **values: object) -> str:
    """The text in that language (English when the language or the key is unknown), with the placeholders filled."""
    table = STRINGS.get(language) or STRINGS["english"]
    template = table.get(key) or STRINGS["english"].get(key) or key
    return template.format(**values) if values else template
